pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _test(uint256 min) internal {
        try c.Initialized() {} catch { return; }
        bool ok = true;
        try c.SetMinSum(min) { } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_test(uint256 min) public {
        _test(min);
    }

    receive() external payable {}
}
